mapper.sql:
WHERE g.delete_yn = 'N'
AND g.use_yn = #{search.useYn}
AND (g.group_code LIKE CONCAT('%', #{search.keyword}, '%') OR g.group_name LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1) FROM tb_code_group
 WHERE group_code = #{groupCode}
   AND delete_yn = 'N'

  AND code_group_id <> #{excludeCodeGroupId}

SELECT COUNT(1) FROM tb_code
 WHERE code_group_id = #{codeGroupId}
   AND delete_yn = 'N'
